import { useState, type ReactNode } from "react";
import { AutomationIcon, InstagramMarkIcon, SearchIcon, PlusIcon, ChevronDownIcon, CheckCircleIcon } from "../components/icons";

export type FullPreviewScreen = "overview" | "automations" | "builder" | "inbox" | "leads" | "lead-detail" | "knowledge" | "content" | "analytics" | "integrations" | "team" | "billing" | "settings" | "docs" | "login" | "connect-error" | "invite";
type Go = (screen: FullPreviewScreen) => void;
function Tag({ children, tone = "neutral" }: { children: ReactNode; tone?: string }) { return <span className={"po-tag po-tag--" + tone}>{children}</span>; }
function Panel({ children, className = "" }: { children: ReactNode; className?: string }) { return <section className={"po-content-panel " + className}>{children}</section>; }
function PanelTitle({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) {
  return <header className="po-panel-title"><div>{eyebrow && <span className="po-eyebrow">{eyebrow}</span>}<h2>{title}</h2>{description && <p>{description}</p>}</div>{action}</header>;
}
function Metric({ label, value, note }: { label: string; value: string; note: string }) { return <div className="po-metric"><span>{label}</span><strong>{value}</strong><small>{note}</small></div>; }
const sampleConversations = [
  { handle:"@sample_fitness", preview:"Do you have pricing for 1:1 coaching?", time:"2m", status:"AI handling", tone:"purple", initial:"SF" },
  { handle:"@studio_owner", preview:"Can you share the class schedule?", time:"12m", status:"Needs review", tone:"amber", initial:"SO" },
  { handle:"@maya_runs", preview:"Is this available for beginners?", time:"27m", status:"AI handling", tone:"purple", initial:"MR" },
];


export function OverviewScreen({ onNavigate }: { onNavigate: Go }) {
  const [period, setPeriod] = useState("Last 7 days");
  const [definitions, setDefinitions] = useState(false);
  return <section>
    <div className="po-screen-toolbar"><span className="po-sample-label">SAMPLE WORKSPACE DATA · NOT LIVE METRICS</span><label className="po-select-wrap"><span className="po-visually-hidden">Reporting period</span><select value={period} onChange={e=>setPeriod(e.target.value)}><option>Last 7 days</option><option>Last 30 days</option><option>This month</option><option>All time</option></select><ChevronDownIcon/></label></div>
    <div className="po-metric-row po-overview-metrics"><Metric label="New leads" value="19" note={"in " + period.toLowerCase()}/><Metric label="Qualified leads" value="0" note="no qualified lead sample"/><Metric label="Meetings scheduled" value="0" note="no meeting records in sample"/><Metric label="Revenue" value="—" note="Revenue tracking not configured"/></div>
    <div className="po-overview-grid">
      <Panel><PanelTitle eyebrow="CONVERSATION VOLUME" title="Activity over time" description="Count of inbound comments and DMs. Not a conversion rate." action={<button type="button" className="po-text-action" onClick={()=>onNavigate("analytics")}>Open analytics →</button>}/><div className="po-chart-summary"><strong>164</strong><span>inbound events · illustrative period: {period}</span></div><div className="po-minibars" role="img" aria-label="Illustrative daily conversation volume">{[18,26,21,34,25,32,8].map((n,i)=><div className="po-minibar-col" key={i}><div className="po-minibar-track"><span style={{height:Math.max(5,n/34*100)+"%"}}/></div><small>{["Mon","Tue","Wed","Thu","Fri","Sat","Sun"][i]}</small></div>)}</div></Panel>
      <Panel><PanelTitle eyebrow="LEAD PIPELINE" title="24 leads by stage" description="Unique lead records; totals reconcile." action={<button type="button" className="po-text-action" onClick={()=>onNavigate("leads")}>View leads →</button>}/><div className="po-stage-list">{[["New",19],["Contacted",3],["Qualified",2]].map(([name,n])=><div className="po-stage-row" key={name as string}><span>{name}</span><div className="po-stage-track"><span style={{width:Number(n)/24*100+"%"}}/></div><strong>{n}</strong><Tag>{Math.round(Number(n)/24*100)}%</Tag></div>)}</div><div className="po-note-line"><CheckCircleIcon/><span>19 + 3 + 2 = 24 leads; no unclassified sample leads.</span></div></Panel>
      <Panel><PanelTitle eyebrow="NEXT ACTIONS" title="Needs your attention" description="Tasks that need an operator." action={<Tag tone="warning">4 items</Tag>}/>{[["Review conversations","2 conversations need a human review","inbox"],["Assign lead owners","2 leads are unassigned","leads"],["Finish an automation draft","Lead qualification is not live","builder"],["Check account health","Review permissions and last event","integrations"]].map((item,i)=><button type="button" className="po-action-row" key={item[0]} onClick={()=>onNavigate(item[2] as FullPreviewScreen)}><span className="po-action-number">0{i+1}</span><span><strong>{item[0]}</strong><small>{item[1]}</small></span><span className="po-action-arrow">→</span></button>)}</Panel>
      <Panel><PanelTitle eyebrow="RECENT CONVERSATIONS" title="Latest activity" description="Recent sample inbound messages." action={<button type="button" className="po-text-action" onClick={()=>onNavigate("inbox")}>Open inbox →</button>}/><div className="po-recent-list">{sampleConversations.map(item=><button type="button" className="po-recent-item" key={item.handle} onClick={()=>onNavigate("inbox")}><span className="po-avatar">{item.initial}</span><span><strong>{item.handle}</strong><small>{item.preview}</small></span><Tag tone={item.tone}>{item.status}</Tag><small>{item.time}</small></button>)}</div></Panel>
    </div>
    <button type="button" className="po-help-text" onClick={()=>setDefinitions(v=>!v)}>{definitions?"Hide metric definitions ↑":"How are these metrics counted? ↓"}</button>{definitions&&<div className="po-definition-block"><strong>Metric definitions</strong><p>Lead metrics count unique lead records. Conversation volume counts events, so one person may send multiple messages. Activity is not a lead conversion rate.</p></div>}
  </section>;
}

const automationRows = [
  {id:"1",name:"Lead qualification",summary:"Ask what the person needs, then capture the answer",trigger:"Comment or DM keywords",account:"@creatorstudio",status:"Draft",updated:"Today"},
  {id:"2",name:"Pricing enquiries",summary:"Answer common price questions from business knowledge",trigger:"DM keyword",account:"@creatorstudio",status:"Live",updated:"Yesterday"},
  {id:"3",name:"New post comments",summary:"Start a conversation when someone comments on a post",trigger:"Comment",account:"@creatorstudio",status:"Live",updated:"Oct 10"},
  {id:"4",name:"Class schedule help",summary:"Share a schedule and offer human follow-up",trigger:"DM keyword",account:"@studioaccount",status:"Paused",updated:"Oct 08"},
  {id:"5",name:"Product interest capture",summary:"Collect the product category a person is interested in",trigger:"Comment",account:"Account not assigned",status:"Draft",updated:"Oct 06"},
];
const templates = [
  {name:"Qualify new leads",outcome:"Ask one or two questions and capture the answer on the lead.",trigger:"Comment or DM",flow:"Trigger → AI reply → Goal",note:"Best starting point"},
  {name:"Answer common questions",outcome:"Use approved business knowledge to answer enquiries.",trigger:"Direct message",flow:"Trigger → Knowledge-backed reply",note:"Requires ready knowledge"},
  {name:"Route complex questions",outcome:"Spot uncertain questions and guide a person into the conversation.",trigger:"Direct message",flow:"Trigger → Reply guidance",note:"Review escalation rules"},
];
export function AutomationsScreen({onOpenBuilder}:{onOpenBuilder:(name:string,status?:string,newDraft?:boolean)=>void}) {
  const [tab,setTab]=useState("mine"); const [showCreate,setShowCreate]=useState(false); const [draftName,setDraftName]=useState(""); const [draftKeywords,setDraftKeywords]=useState("price, quote, details"); const [draftTrigger,setDraftTrigger]=useState("comment"); const [query,setQuery]=useState(""); const [status,setStatus]=useState("All statuses"); const [trigger,setTrigger]=useState("All start conditions"); const [sort,setSort]=useState("Recently updated"); const [notice,setNotice]=useState("");
  const filtered=automationRows.filter(r=>(!query||(r.name+" "+r.summary+" "+r.account).toLowerCase().includes(query.toLowerCase()))&&(status==="All statuses"||r.status===status)&&(trigger==="All start conditions"||r.trigger===trigger));
  const rows=[...filtered].sort((a,b)=>sort==="Name A–Z"?a.name.localeCompare(b.name):sort==="Status"?a.status.localeCompare(b.status):0);
  return <section><div className="po-outcome-banner"><span className="po-outcome-marker"><AutomationIcon/></span><div><strong>Start with the outcome you want.</strong><p>Choose a starting point, review each step, and publish only when you are ready.</p></div><button type="button" className="po-button po-button--primary" onClick={()=>setShowCreate(true)}>Create draft</button></div>
    <div className="po-tab-bar" role="tablist" aria-label="Automation list views"><button type="button" role="tab" aria-selected={tab==="mine"} className={tab==="mine"?"is-active":""} onClick={()=>setTab("mine")}>My automations <span>5</span></button><button type="button" role="tab" aria-selected={tab==="templates"} className={tab==="templates"?"is-active":""} onClick={()=>setTab("templates")}>Start from a template <span>3</span></button></div>
    {tab==="mine"?<><div className="po-list-toolbar"><div><h2>Automation library</h2><p>Identify each journey by trigger, account, status, and last update.</p></div><div className="po-table-controls"><label className="po-search"><SearchIcon/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search automations"/></label><label className="po-select-wrap"><span className="po-visually-hidden">Status filter</span><select value={status} onChange={e=>setStatus(e.target.value)}><option>All statuses</option><option>Draft</option><option>Live</option><option>Paused</option></select><ChevronDownIcon/></label><label className="po-select-wrap"><span className="po-visually-hidden">Start condition</span><select value={trigger} onChange={e=>setTrigger(e.target.value)}><option>All start conditions</option><option>Comment</option><option>DM keyword</option><option>Comment or DM keywords</option></select><ChevronDownIcon/></label><label className="po-select-wrap"><span className="po-visually-hidden">Sort</span><select value={sort} onChange={e=>setSort(e.target.value)}><option>Recently updated</option><option>Name A–Z</option><option>Status</option></select><ChevronDownIcon/></label></div></div>{notice&&<div className="po-inline-notice" role="status">{notice}</div>}<div className="po-automation-table-wrap"><table className="po-automation-table"><thead><tr><th>Automation</th><th>Starts when</th><th>Instagram account</th><th>Status</th><th>Updated</th><th>Actions</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td><button type="button" className="po-table-primary-link" onClick={()=>onOpenBuilder(r.name,r.status,false)}>{r.name}</button><small>{r.summary}</small></td><td>{r.trigger}</td><td>{r.account}</td><td><Tag tone={r.status==="Live"?"green":r.status==="Draft"?"warning":"neutral"}>{r.status}</Tag></td><td>{r.updated}</td><td><div className="po-row-actions"><button type="button" onClick={()=>onOpenBuilder(r.name,r.status,false)}>Edit</button><button type="button" onClick={()=>setNotice("Duplicate confirmation for "+r.name+"; no record was created.")}>Duplicate</button><button type="button" onClick={()=>setNotice("Delete confirmation for "+r.name+"; no record was deleted.")}>Delete</button></div></td></tr>)}</tbody></table>{rows.length===0&&<div className="po-table-empty"><strong>No automations match</strong><span>Clear the search or change a filter.</span></div>}</div><p className="po-help-text">Illustrative records only. Production workspace automations are not loaded.</p></>:<div className="po-template-grid">{templates.map((t,i)=><article className="po-template-card" key={t.name}><div className="po-template-top"><span className="po-template-number">0{i+1}</span><Tag>{t.note}</Tag></div><h2>{t.name}</h2><p>{t.outcome}</p><div className="po-template-metadata"><span><small>TRIGGER</small><strong>{t.trigger}</strong></span><span><small>FLOW</small><strong>{t.flow}</strong></span></div><button type="button" className="po-button po-button--secondary" onClick={()=>onOpenBuilder(t.name,"Draft",true)}>Use this template →</button></article>)}</div>}
  {showCreate&&<div className="po-modal-backdrop" role="presentation" onMouseDown={e=>e.target===e.currentTarget&&setShowCreate(false)}><section className="po-modal" role="dialog" aria-modal="true" aria-labelledby="po-create-draft-title"><div className="po-modal-top"><span className="po-eyebrow">NEW AUTOMATION · PREVIEW</span><button type="button" className="po-icon-button" aria-label="Close draft dialog" onClick={()=>setShowCreate(false)}>×</button></div><h2 id="po-create-draft-title">Create a draft</h2><p>Choose a clear name and start condition. This creates a local preview draft only; it doesn't create a server record.</p><label className="po-field-block">Automation name<input value={draftName} onChange={e=>setDraftName(e.target.value)} placeholder="e.g. Pricing enquiries" maxLength={100}/></label><label className="po-field-block">Start condition<select value={draftTrigger} onChange={e=>setDraftTrigger(e.target.value)}><option value="comment">Instagram comments</option><option value="message">Direct messages</option><option value="both">Comments and direct messages</option></select></label><label className="po-field-block">Keywords<textarea rows={3} value={draftKeywords} onChange={e=>setDraftKeywords(e.target.value)} placeholder="price, quote, details"/></label><div className="po-modal-footer"><button type="button" className="po-button po-button--secondary" onClick={()=>setShowCreate(false)}>Cancel</button><button type="button" className="po-button po-button--primary" disabled={!draftName.trim()||!draftKeywords.trim()} onClick={()=>{onOpenBuilder(draftName.trim(),"Draft",true);setShowCreate(false);}}>Continue to builder</button></div></section></div>}</section>;
}

export function LeadDetailScreen({leadName,onBack,onNavigate}:{leadName:string;onBack:()=>void;onNavigate:Go}) {
  const [tab,setTab]=useState("Overview"); const [stage,setStage]=useState("New"); const [owner,setOwner]=useState("Needs assignment"); const [handoff,setHandoff]=useState(true); const [notes,setNotes]=useState(""); const [savedNotes,setSavedNotes]=useState<string[]>([]); const [showScore,setShowScore]=useState(false); const [tagInput,setTagInput]=useState(""); const [tags,setTags]=useState(["Interested"]); const [notice,setNotice]=useState(""); const [dealOpen,setDealOpen]=useState(false); const [dealValue,setDealValue]=useState("25000");
  return <section className="po-lead-detail-screen"><div className="po-lead-detail-toolbar"><button type="button" className="po-button po-button--quiet" onClick={onBack}>← Back to leads</button><div className="po-lead-profile-heading"><span className="po-avatar po-avatar--large">ML</span><div><h2>{leadName}</h2><p>@morgan.sample · Instagram lead · sample record</p></div><Tag tone={handoff?"blue":"purple"}>{handoff?"Human is replying":"AI handling"}</Tag></div><button type="button" className="po-button po-button--secondary" onClick={()=>setHandoff(v=>!v)}>{handoff?"Return to AI (demo)":"Take over (demo)"}</button></div>
    <div className="po-lead-tabs" role="tablist" aria-label="Lead detail sections">{["Overview","Conversation","Activities","Notes"].map(t=><button type="button" role="tab" aria-selected={tab===t} className={tab===t?"is-active":""} key={t} onClick={()=>setTab(t)}>{t}</button>)}</div>
    {tab==="Overview"&&<div className="po-detail-grid"><div className="po-detail-main"><Panel><PanelTitle title="Lead details" description="Business-friendly fields and clear ownership."/><div className="po-detail-fields"><label>Pipeline stage<select value={stage} onChange={e=>setStage(e.target.value)}>{["New","Contacted","Qualified","Meeting Scheduled","Won","Lost"].map(s=><option key={s}>{s}</option>)}</select></label><label>Owner<select value={owner} onChange={e=>setOwner(e.target.value)}>{["Needs assignment","Alex Morgan","Sam Taylor","Queue — Sales follow-up"].map(s=><option key={s}>{s}</option>)}</select></label><label>Source<span className="po-readonly-field">Instagram comment</span></label><label>Last activity<span className="po-readonly-field">2 minutes ago · sample</span></label></div>{handoff&&owner==="Needs assignment"&&<div className="po-warning-note"><span>!</span><span><strong>Needs assignment</strong><small>This lead is in human handling but has no owner. Assign a teammate or a follow-up queue.</small></span></div>}</Panel>
    <Panel><PanelTitle title="Captured facts" description="Information collected during the conversation."/><div className="po-captured-facts"><div><span>Interest</span><strong>1:1 coaching</strong></div><div><span>Preferred timeline</span><strong>Within this month</strong></div></div><div className="po-tag-editor">{tags.map(tag=><button type="button" key={tag} className="po-tag-removable" onClick={()=>setTags(v=>v.filter(x=>x!==tag))}><Tag>{tag} ×</Tag></button>)}</div><div className="po-inline-add"><input value={tagInput} onChange={e=>setTagInput(e.target.value)} placeholder="Add lead tag"/><button type="button" className="po-button po-button--secondary" disabled={!tagInput.trim()} onClick={()=>{setTags(v=>v.concat(tagInput.trim()));setTagInput("");}}>Add tag</button></div><button type="button" className="po-text-action" onClick={()=>onNavigate("settings")}>Manage captured fields →</button></Panel>
    <Panel><PanelTitle title="Lead intelligence" description="Explain score, signals, and calculation time." action={<Tag>Not calculated</Tag>}/><p className="po-panel-copy">Scoring needs configured rules and enough conversation signals. This preview doesn't call scoring services or consume tokens.</p><button type="button" className="po-button po-button--secondary" onClick={()=>setShowScore(v=>!v)}>What would be calculated?</button>{showScore&&<div className="po-definition-block"><strong>Example scoring signals</strong><p>Stated interest, timeline, engagement intent, and configured scoring rules. In production, show when the score was calculated and which rules contributed.</p></div>}</Panel>
    <Panel><PanelTitle title="Deals" description="Potential revenue associated with this lead."/><div className="po-empty-detail"><strong>No deal linked</strong><span>Illustrate deal value without creating real sales records.</span></div>{dealOpen?<div className="po-add-field"><label>Estimated value (INR)<input inputMode="numeric" value={dealValue} onChange={e=>setDealValue(e.target.value)}/></label><button type="button" className="po-button po-button--primary" onClick={()=>{setNotice("Example deal ₹"+dealValue+" recorded in local preview state only.");setDealOpen(false);}}>Add example deal</button></div>:<button type="button" className="po-button po-button--secondary" onClick={()=>setDealOpen(true)}>Add deal (preview)</button>}</Panel></div><aside className="po-detail-aside"><Panel><h2>Contact</h2><p>@morgan.sample</p><div className="po-detail-row"><span>Handoff</span><Tag tone={handoff?"blue":"purple"}>{handoff?"Human":"AI"}</Tag></div><div className="po-detail-row"><span>Owner</span><strong>{owner}</strong></div><div className="po-detail-row"><span>Stage</span><Tag>{stage}</Tag></div><button type="button" className="po-button po-button--secondary po-full-width" onClick={()=>onNavigate("inbox")}>Open Inbox</button></Panel><Panel><PanelTitle title="Recent activity"/><div className="po-timeline"><div><b>Lead created</b><small>Trigger matched · Today 10:24 AM</small></div><div><b>AI reply recorded</b><small>Example reply · 10:25 AM</small></div></div></Panel></aside></div>}
    {tab==="Conversation"&&<Panel><PanelTitle title="Conversation history" description="Sample timeline · not connected to a live Instagram thread."/><div className="po-messages"><div className="po-message po-message--incoming"><span>Hi, do you have pricing for 1:1 coaching?</span><small>10:24 AM · Sample</small></div><div className="po-message po-message--outgoing"><span>Thanks for reaching out. What are you hoping to achieve?</span><small>10:25 AM · Example AI reply</small></div><div className="po-message po-message--incoming"><span>I'd like to build a routine before the end of the month.</span><small>10:26 AM · Sample</small></div></div><button type="button" className="po-button po-button--secondary" onClick={()=>onNavigate("inbox")}>Open Inbox →</button></Panel>}
    {tab==="Activities"&&<Panel><PanelTitle title="Activity history" description="Actions and state changes for this sample lead."/><div className="po-timeline"><div><b>Lead created</b><small>Comment trigger matched · 10:24 AM</small></div><div><b>AI reply recorded</b><small>Example response · 10:25 AM</small></div><div><b>Qualification captured</b><small>Interest and timeline · 10:26 AM</small></div><div><b>Human follow-up requested</b><small>Owner assignment pending · 10:30 AM</small></div></div></Panel>}
    {tab==="Notes"&&<Panel><PanelTitle title="Team notes" description="Leave context for the next person handling this conversation."/><p className="po-panel-copy">Notes stay local to this preview and clear on refresh.</p><label className="po-field-block">Add a note<textarea rows={4} value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Add context for the next teammate…"/></label><button type="button" className="po-button po-button--primary" disabled={!notes.trim()} onClick={()=>{setSavedNotes(v=>[notes,...v]);setNotes("");}}>Add note</button>{savedNotes.map((n,i)=><div className="po-note-card" key={i}><strong>Sample note · just now</strong><p>{n}</p></div>)}</Panel>}
    {notice&&<div className="po-inline-notice" role="status">{notice}</div>}
  </section>;
}

export function KnowledgeScreen() {
  const [query,setQuery]=useState(""); const [question,setQuestion]=useState(""); const [tested,setTested]=useState(false); const [upload,setUpload]=useState(false); const [selected,setSelected]=useState("pricing-faq.md");
  const all=[{name:"pricing-faq.md",type:"Markdown",size:"18 KB",status:"Ready",updated:"Today, 09:14",tone:"green",summary:"Pricing, packages, coaching options, and service boundaries."},{name:"class-schedule.pdf",type:"PDF",size:"420 KB",status:"Ready",updated:"Yesterday",tone:"green",summary:"Class times, beginner sessions, and booking information."},{name:"brand-voice.md",type:"Markdown",size:"8 KB",status:"Needs review",updated:"Oct 09",tone:"amber",summary:"Tone, prohibited promises, and escalation guidance."},{name:"catalog-2026.pdf",type:"PDF",size:"Processing",status:"Processing",updated:"Just now",tone:"blue",summary:"Product details and current availability."},{name:"old-faq.txt",type:"Text",size:"12 KB",status:"Failed",updated:"Oct 07",tone:"red",summary:"Parsing failed. Replace or retry before using."}];
  const rows=all.filter(s=>s.name.toLowerCase().includes(query.toLowerCase())); const current=rows.find(s=>s.name===selected)??all.find(s=>s.name===selected);
  return <section className="po-knowledge-screen"><div className="po-kb-layout"><Panel className="po-kb-sources"><PanelTitle title="Knowledge sources" description="Ready sources ground AI replies. Processing sources are not ready; failed sources are excluded." action={<button type="button" className="po-button po-button--primary" onClick={()=>setUpload(v=>!v)}><PlusIcon/> Add source</button>}/><label className="po-search"><SearchIcon/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search source files"/></label>{upload&&<div className="po-upload-zone"><strong>Add a knowledge source</strong><p>PDF, Markdown, or plain text. This preview does not upload or index files.</p><input type="file" accept=".pdf,.md,.txt" aria-label="Choose a sample file"/><button type="button" className="po-button po-button--secondary" onClick={()=>setUpload(false)}>Close</button></div>}<div className="po-source-list">{rows.map(s=><button type="button" className={"po-source-row"+(selected===s.name?" is-selected":"")} key={s.name} onClick={()=>{setSelected(s.name);setTested(false);}}><span className="po-source-type">{s.type==="PDF"?"PDF":s.type==="Text"?"TXT":"MD"}</span><span><strong>{s.name}</strong><small>{s.type} · {s.size} · Updated {s.updated}</small><span className="po-source-summary">{s.summary}</span></span><Tag tone={s.tone}>{s.status}</Tag></button>)}</div>{rows.length===0&&<div className="po-table-empty"><strong>No files match</strong><span>Try a different source name.</span></div>}</Panel><aside className="po-content-panel po-kb-inspector"><span className="po-eyebrow">SOURCE DETAILS</span>{current&&<><h2>{current.name}</h2><p>{current.summary}</p><div className="po-detail-row"><span>Index status</span><Tag tone={current.tone}>{current.status}</Tag></div><div className="po-detail-row"><span>Last processed</span><strong>{current.updated}</strong></div><div className="po-detail-row"><span>Extracted sections</span><strong>{current.status==="Failed"?"Unavailable":"14 · sample"}</strong></div>{current.status==="Failed"?<div className="po-warning-note"><span>!</span><span><strong>Source isn't being used</strong><small>Replace the file or retry processing. No extraction runs here.</small></span></div>:<div className="po-definition-block"><strong>Extracted content preview</strong><p>Relevant source evidence should ground a reply. If evidence is missing, ask a follow-up or route to a person.</p></div>}</>}</aside></div><Panel className="po-retrieval-test"><PanelTitle eyebrow="RETRIEVAL CHECK" title="Test a question against knowledge" description="Verify source relevance before using it in a live reply."/><div className="po-test-question"><label>Question<input value={question} onChange={e=>{setQuestion(e.target.value);setTested(false);}} placeholder="e.g. What are the 1:1 coaching prices?"/></label><button type="button" className="po-button po-button--primary" disabled={!question.trim()} onClick={()=>setTested(true)}>Test question</button></div>{tested&&<div className="po-test-result" role="status"><Tag tone="success">Illustrative result</Tag><div><strong>Potential source: {current?.name??"none selected"}</strong><p>No retrieval service was called. Production should show source excerpts and confidence.</p></div></div>}</Panel></section>;
}

export function ContentScreen() {
  const [filter,setFilter]=useState("All media"); const [query,setQuery]=useState(""); const [preview,setPreview]=useState<string|null>(null); const [refreshed,setRefreshed]=useState(false);
  const items=[{id:"p1",type:"Image",title:"Spring coaching offer",caption:"New to training? Start with a plan that fits your week.",comments:42,keywords:"price · coaching · plan",updated:"Synced 8 min ago",art:"coaching"},{id:"p2",type:"Carousel",title:"What to expect in week one",caption:"A simple routine, practical guidance, and measurable progress.",comments:28,keywords:"beginner · routine · details",updated:"Synced 8 min ago",art:"routine"},{id:"p3",type:"Video",title:"A quick look at the studio",caption:"Here is what a first session looks like.",comments:17,keywords:"studio · session",updated:"Synced 11 min ago",art:"studio"}].filter(item=>(filter==="All media"||item.type===filter)&&(item.title+" "+item.caption+" "+item.keywords).toLowerCase().includes(query.toLowerCase()));
  return <section className="po-content-screen"><div className="po-screen-toolbar"><div className="po-filter-tabs" role="group" aria-label="Filter content by type">{["All media","Image","Carousel","Video"].map(v=><button type="button" className={filter===v?"is-active":""} key={v} onClick={()=>setFilter(v)}>{v}</button>)}</div><label className="po-search"><SearchIcon/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search captions and keywords"/></label></div><div className="po-content-status-line"><span>Sample Instagram account · @creatorstudio</span><button type="button" className="po-text-action" onClick={()=>setRefreshed(true)}>Refresh posts ↻</button><span role="status">{refreshed?"Sample refresh checked just now":"Last sync appears on each card"}</span></div><div className="po-content-cards">{items.map(item=><article className="po-post-card" key={item.id}><button type="button" className={"po-post-art po-post-art--"+item.art} onClick={()=>setPreview(item.id)} aria-label={"Preview "+item.title}><span className="po-post-art-label">{item.type.toUpperCase()} · SAMPLE ART</span><strong>{item.title}</strong><span className="po-post-art-bottom">@creatorstudio <InstagramMarkIcon/></span></button><div className="po-post-body"><div className="po-post-meta"><Tag>{item.type}</Tag><span>{item.updated}</span></div><h2>{item.title}</h2><p>{item.caption}</p><div className="po-post-context-row"><span>{item.comments} comments</span><span>Trigger terms: {item.keywords}</span></div><div className="po-post-actions"><button type="button" className="po-button po-button--secondary" onClick={()=>setPreview(item.id)}>Preview post</button><button type="button" className="po-button po-button--quiet" onClick={()=>setPreview(item.id)}>Review comments →</button></div></div></article>)}</div>{items.length===0&&<div className="po-table-empty"><strong>No posts match</strong><span>Change the media filter or search term.</span></div>}{preview&&<div className="po-modal-backdrop" role="presentation" onMouseDown={e=>e.target===e.currentTarget&&setPreview(null)}><section className="po-modal" role="dialog" aria-modal="true" aria-labelledby="po-content-modal-title"><div className="po-modal-top"><span className="po-eyebrow">POST PREVIEW · SAMPLE</span><button type="button" className="po-icon-button" aria-label="Close post preview" onClick={()=>setPreview(null)}>×</button></div>{(()=>{const item=items.find(v=>v.id===preview);return item?<><div className={"po-post-art po-post-art--"+item.art}><span className="po-post-art-label">{item.type.toUpperCase()} · SAMPLE ART</span><strong>{item.title}</strong></div><h2 id="po-content-modal-title">{item.title}</h2><p>{item.caption}</p><div className="po-detail-row"><span>Comments</span><strong>{item.comments} · sample</strong></div><div className="po-detail-row"><span>Trigger terms</span><strong>{item.keywords}</strong></div></>:null;})()}<div className="po-modal-footer"><button type="button" className="po-button po-button--secondary" onClick={()=>setPreview(null)}>Close</button></div></section></div>}</section>;
}

export function AnalyticsScreen() {
  const [tab,setTab]=useState("Activity"); const [period,setPeriod]=useState("Last 7 days"); const [definitions,setDefinitions]=useState(false);
  return <section className="po-analytics-screen"><div className="po-analytics-controls"><div className="po-tab-bar" role="tablist" aria-label="Analytics views"><button type="button" role="tab" aria-selected={tab==="Activity"} className={tab==="Activity"?"is-active":""} onClick={()=>setTab("Activity")}>Activity volume</button><button type="button" role="tab" aria-selected={tab==="Conversion"} className={tab==="Conversion"?"is-active":""} onClick={()=>setTab("Conversion")}>Lead conversion</button></div><label className="po-select-wrap"><span className="po-visually-hidden">Analytics date range</span><select value={period} onChange={e=>setPeriod(e.target.value)}><option>Last 7 days</option><option>Last 30 days</option><option>This month</option><option>All time</option></select><ChevronDownIcon/></label></div>
    {tab==="Activity"?<><div className="po-metric-row"><Metric label="Comments received" value="10" note={"in "+period.toLowerCase()}/><Metric label="Direct messages" value="154" note="inbound event count"/><Metric label="Replies sent" value="128" note="sample events"/><Metric label="Human handoffs" value="7" note="sample routing events"/></div><Panel><PanelTitle eyebrow="INBOUND ACTIVITY" title="Messages and comments over time" description="Events can repeat from the same lead; these are not conversion rates."/><div className="po-minibars" role="img" aria-label="Illustrative activity over seven days">{[18,24,17,29,33,22,31].map((n,i)=><div className="po-minibar-col" key={i}><div className="po-minibar-track"><span style={{height:n/33*100+"%"}}/></div><small>{["Mon","Tue","Wed","Thu","Fri","Sat","Sun"][i]}</small></div>)}</div><div className="po-data-table-scroll"><table className="po-automation-table"><thead><tr><th>Event type</th><th>Count</th><th>Definition</th></tr></thead><tbody><tr><td>Comments received</td><td>10</td><td>Inbound comment events</td></tr><tr><td>Direct messages</td><td>154</td><td>Inbound DM events, including repeats</td></tr><tr><td>Replies sent</td><td>128</td><td>AI or team replies recorded</td></tr><tr><td>Human handoffs</td><td>7</td><td>Conversation control routed to a person</td></tr></tbody></table></div></Panel></>:<><div className="po-metric-row"><Metric label="Unique leads" value="24" note="sample pipeline"/><Metric label="Qualified" value="2" note="8.3% of leads"/><Metric label="Contacted" value="3" note="12.5% of leads"/><Metric label="Won" value="0" note="none in sample"/></div><Panel><PanelTitle eyebrow="CURRENT PIPELINE" title="Lead stage distribution" description="Unique lead records by current stage; totals reconcile to 24."/><div className="po-stage-list po-stage-list--large">{[["New",19,"79%"],["Contacted",3,"13%"],["Qualified",2,"8%"],["Won",0,"0%"]].map(([name,n,p])=><div className="po-stage-row" key={name as string}><span>{name}</span><div className="po-stage-track"><span style={{width:p as string}}/></div><strong>{n}</strong><Tag>{p}</Tag></div>)}</div></Panel></>}
    <button type="button" className="po-help-text" onClick={()=>setDefinitions(v=>!v)}>{definitions?"Hide definitions ↑":"Show metric definitions and attribution ↓"}</button>{definitions&&<div className="po-definition-block"><strong>Reporting definitions</strong><p>All values are illustrative. Activity counts events, while conversion counts unique lead records. Production metrics need a period, cohort, denominator, and attribution rule.</p></div>}
    <div className="po-overview-grid"><Panel><PanelTitle title="Top performing posts" description="Posts ranked by sample comment activity."/><table className="po-automation-table"><thead><tr><th>Post</th><th>Comments</th></tr></thead><tbody><tr><td>Spring coaching offer</td><td>16</td></tr><tr><td>Week one guide</td><td>2</td></tr></tbody></table></Panel><Panel><PanelTitle title="Top trigger keywords" description="Counts show trigger matches, not lead conversions."/><div className="po-keyword-list">{[["ongoing conversation",112],["product",17],["signalAI",8],["details",7],["nice",5]].map(([w,n])=><div key={w as string}><span>{w}</span><strong>{n}</strong></div>)}</div></Panel></div>
  </section>;
}

